          try { v = await kv.get(k); } catch (e1) { v = null; }
          if (v) { if (ty === 'json') { try { return JSON.parse(v); } catch (e2) { return null; } } return v; }
          if (memo[uid] !== undefined) {
            var mo = memo[uid];
            if (ty === 'json') { try { return mo ? JSON.parse(mo) : null; } catch (e3) { return null; } }
            return mo;
          }
          var okm = await __skMember(kv, uid);
          var out = okm ? JSON.stringify({ ok: 1, ver: 3, at: Date.now() }) : null;
          memo[uid] = out;
